@contextmanager
def original_step():
    from chaos import suspension
    namespace = {}
    # Execute the frozen original method against the same real runtime classes;
    # no replacement scheduler, task, callback or effect semantics are invented.
    exec(compile(ORIGINAL_STEP, '<original-suspension239-step>', 'exec'), vars(suspension), namespace)
    with patch.object(suspension.Scheduler, '_step', namespace['_step']):
        yield
